using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;
public static class StairAWalk {
 static Vector3 C=new Vector3(-44,-82,28);static Vector3 V(float x,float y,float z)=>C+new Vector3(x,y,z);
 static Vector3[] Steps(){var points=new List<Vector3>{V(-.96f,0,-2.38f)};for(int f=0;f<8;f++){float x=f%2==0?-.96f:.96f;float d=f%2==0?1:-1;float z0=-1.68f*d;for(int i=0;i<12;i++)points.Add(V(x,f*2+(i+1)/6f,z0+d*(i+.5f)*.28f));points.Add(V(x,f*2+2,-z0+d*.70f));if(f<7)points.Add(V(-x,f*2+2,-z0+d*.70f));}return points.ToArray();}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var start=player.transform.position;bool was=cc.enabled;var routes=new Dictionary<string,Vector3[]>();var stairs=Steps();routes["stairs_up"]=stairs;routes["stairs_down"]=stairs.Reverse().ToArray();var east=new[]{new Vector3(-22,-82,18),new Vector3(-39.85f,-82,26.11f),V(2.5f,0,-1.65f),V(2.3f,0,-2.4f),V(-.96f,0,-2.38f)};routes["T02_to_stairs"]=east;routes["stairs_to_T02"]=east.Reverse().ToArray();routes["T08_to_stairs"]=new[]{V(-5.1f,0,1.16f),V(-2.7f,0,.8f),V(-2.7f,0,-2.38f),V(-.96f,0,-2.38f)};routes["T16_to_stairs"]=new[]{V(3.5f,0,3.82f),V(2.8f,0,2.4f),V(2.8f,0,-2.4f),V(-.96f,0,-2.38f)};var results=new List<object>();try{foreach(var route in routes){cc.enabled=false;player.transform.position=route.Value[0]+Vector3.up*(cc.height*.5f-cc.center.y+.035f);cc.enabled=true;Physics.SyncTransforms();int steps=0;bool passed=true;float remaining=0;Vector3 target=route.Value[0];foreach(var to in route.Value.Skip(1)){target=to;int limit=(int)(Vector3.Distance(player.transform.position,to)/.05f)+90;for(int i=0;i<limit;i++){var d=to-player.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.025f)break;cc.Move(d.normalized*Mathf.Min(.05f,remaining)+Vector3.down*.045f);steps++;}if(remaining>.08f){passed=false;break;}}for(int i=0;i<12;i++)cc.Move(Vector3.down*.035f);float bottom=player.transform.position.y+cc.center.y-cc.height*.5f;float heightError=bottom-target.y;if(Mathf.Abs(heightError)>.30f)passed=false;results.Add(new{id=route.Key,passed,steps,remaining,heightError,foot=new[]{player.transform.position.x,bottom,player.transform.position.z},target=new[]{target.x,target.y,target.z}});}}finally{cc.enabled=false;player.transform.position=start;cc.enabled=was;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}var result=new{radius=cc?cc.radius:.28f,results};string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));File.WriteAllText(repo+"/Docs/검수/2026-11-08_T02_StairA/walk.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
